int replace_net_table(struct net *net, const void __user *user, unsigned int len)
{
    struct temp_table_data *tmp;
    int num_entries, ret = 0;
    size_t alloc_size;

    if (len % sizeof(struct table_entry) != 0)
        return -EINVAL;

    num_entries = len / sizeof(struct table_entry);
    if (num_entries <= 0)
        return -EINVAL;

    if (num_entries > MAX_ENTRIES)
        return -EOVERFLOW;

    tmp = kmalloc(len, GFP_KERNEL);
    if (!tmp)
        return -ENOMEM;

    if (copy_from_user(tmp, user, len)) {
        kfree(tmp);
        return -EFAULT;
    }

    alloc_size = num_entries * sizeof(struct table_entry);
    net->table = kmalloc(alloc_size, GFP_KERNEL);
    if (!net->table) {
        kfree(tmp);
        return -ENOMEM;
    }

    if (copy_from_user(net->table, user, len)) {
        kfree(tmp);
        kfree(net->table);
        return -EFAULT;
    }

    ret = finish_table_replacement(net, tmp, len);
    if (ret < 0) {
        kfree(tmp);
        kfree(net->table);
        net->table = NULL;
    }

    kfree(tmp);
    return ret;
}

